**`CheckoutPage.tsx`**
```tsx
import React, { useMemo, useState } from "react";
import "./CheckoutPage.css";

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  imageUrl?: string;
}

export interface DeliveryAddress {
  fullName: string;
  addressLine1: string;
  addressLine2: string;
  city: string;
  postalCode: string;
  country: string;
  phone: string;
}

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => Promise<void> | void;
}

type FormErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: "",
  addressLine1: "",
  addressLine2: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

const REQUIRED_FIELDS: (keyof DeliveryAddress)[] = [
  "fullName",
  "addressLine1",
  "city",
  "postalCode",
  "country",
  "phone",
];

function formatPrice(value: number): string {
  return value.toLocaleString(undefined, {
    style: "currency",
    currency: "USD",
  });
}

export default function CheckoutPage({
  items,
  onBackToCart,
  onPay,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<FormErrors>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const shipping = items.length > 0 ? 4.99 : 0;
  const total = subtotal + shipping;

  function handleChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  }

  function validate(): boolean {
    const nextErrors: FormErrors = {};
    REQUIRED_FIELDS.forEach((field) => {
      if (!address[field].trim()) {
        nextErrors[field] = "This field is required.";
      }
    });
    if (
      address.postalCode &&
      !/^[a-zA-Z0-9\s-]{3,10}$/.test(address.postalCode.trim())
    ) {
      nextErrors.postalCode = "Enter a valid postal code.";
    }
    if (address.phone && !/^[+0-9\s()-]{6,20}$/.test(address.phone.trim())) {
      nextErrors.phone = "Enter a valid phone number.";
    }
    setErrors(nextErrors);
    return Object.keys(nextErrors).length === 0;
  }

  async function handlePay(e: React.FormEvent) {
    e.preventDefault();
    setPayError(null);

    if (items.length === 0) {
      setPayError("Your cart is empty.");
      return;
    }
    if (!validate()) {
      return;
    }

    setIsPaying(true);
    try {
      await onPay(address);
    } catch {
      setPayError("Payment failed. Please try again.");
    } finally {
      setIsPaying(false);
    }
  }

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          disabled={isPaying}
        >
          ← Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="checkout-section cart-summary" aria-label="Order summary">
          <h2>Your items</h2>
          {items.length === 0 ? (
            <p className="empty-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-image-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="order-totals">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>{formatPrice(shipping)}</span>
            </div>
            <div className="totals-row totals-row-total">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section delivery-form" aria-label="Delivery address">
          <h2>Delivery address</h2>
          <form onSubmit={handlePay} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={(e) => handleChange("fullName", e.target.value)}
                aria-invalid={!!errors.fullName}
                aria-describedby={errors.fullName ? "fullName-error" : undefined}
              />
              {errors.fullName && (
                <span id="fullName-error" className="field-error">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="addressLine1">Address line 1</label>
              <input
                id="addressLine1"
                type="text"
                value={address.addressLine1}
                onChange={(e) => handleChange("addressLine1", e.target.value)}
                aria-invalid={!!errors.addressLine1}
                aria-describedby={
                  errors.addressLine1 ? "addressLine1-error" : undefined
                }
              />
              {errors.addressLine1 && (
                <span id="addressLine1-error" className="field-error">
                  {errors.addressLine1}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="addressLine2">Address line 2 (optional)</label>
              <input
                id="addressLine2"
                type="text"
                value={address.addressLine2}
                onChange={(e) => handleChange("addressLine2", e.target.value)}
              />
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={(e) => handleChange("city", e.target.value)}
                  aria-invalid={!!errors.city}
                  aria-describedby={errors.city ? "city-error" : undefined}
                />
                {errors.city && (
                  <span id="city-error" className="field-error">
                    {errors.city}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={(e) => handleChange("postalCode", e.target.value)}
                  aria-invalid={!!errors.postalCode}
                  aria-describedby={
                    errors.postalCode ? "postalCode-error" : undefined
                  }
                />
                {errors.postalCode && (
                  <span id="postalCode-error" className="field-error">
                    {errors.postalCode}
                  </span>
                )}
              </div>
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="country">Country</label>
                <input
                  id="country"
                  type="text"
                  value={address.country}
                  onChange={(e) => handleChange("country", e.target.value)}
                  aria-invalid={!!errors.country}
                  aria-describedby={errors.country ? "country-error" : undefined}
                />
                {errors.country && (
                  <span id="country-error" className="field-error">
                    {errors.country}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="phone">Phone</label>
                <input
                  id="phone"
                  type="tel"
                  value={address.phone}
                  onChange={(e) => handleChange("phone", e.target.value)}
                  aria-invalid={!!errors.phone}
                  aria-describedby={errors.phone ? "phone-error" : undefined}
                />
                {errors.phone && (
                  <span id="phone-error" className="field-error">
                    {errors.phone}
                  </span>
                )}
              </div>
            </div>

            {payError && <p className="pay-error">{payError}</p>}

            <div className="checkout-actions">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={onBackToCart}
                disabled={isPaying}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={isPaying || items.length === 0}
              >
                {isPaying ? "Processing…" : `Pay ${formatPrice(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

